any/assignment.pxf.format:
@type any.v1.Holder

# Accept: the = { } spelling of the same value.
payload = {
  @type = "any.v1.Leaf"
  tag = "t"
}

any/block.pxf.format:
@type any.v1.Holder

# Accept: a type entry opens the block; the rest is a body of any.v1.Leaf.
payload {
  @type = "any.v1.Leaf"
  tag = "t"
  n = 7
}

any/err-not-any.pxf.format:
@type any.v1.Holder

# Reject: leaf is an any.v1.Leaf, not a google.protobuf.Any.
leaf {
  @type = "any.v1.Leaf"
  tag = "t"
}

any/err-unresolved.pxf.format:
@type any.v1.Holder

# Reject: the type URL names no type the resolver knows.
payload {
  @type = "any.v1.Nope"
  tag = "t"
}

any/list-element.pxf.format:
@type any.v1.Holder

# Accept: each element of a repeated Any may open with a type entry.
anys = [
  {
    @type = "any.v1.Leaf"
    tag = "a"
  },
  {
    @type = "any.v1.Leaf"
    n = 2
  }
]

any/list-element.pxf.marshal:
anys = [
  {
    type_url = "any.v1.Leaf"
    value = b"CgFh"
  },
  {
    type_url = "any.v1.Leaf"
    value = b"EAI="
  }
]

any/map-value.pxf.format:
@type any.v1.Holder

# Accept: a map value of type Any may open with a type entry.
by_key = {
  k: {
    @type = "any.v1.Leaf"
    tag = "t"
  }
}

any/plain-fields.pxf.format:
@type any.v1.Holder

# Accept: without a type entry an Any block is its own fields.
# CgF0 is any.v1.Leaf{tag: "t"}.
payload = {
  type_url = "any.v1.Leaf"
  value = b"CgF0"
}

any/url-verbatim.pxf.format:
@type any.v1.Holder

# Accept: the type URL is stored in type_url exactly as written.
payload {
  @type = "type.googleapis.com/any.v1.Leaf"
  tag = "t"
}

blocks/comma-between-elements.pxf.format:
@type blocks.v1.Doc

# Accept: commas between list elements, each a block whose entries
# are separated by spaces. Binds two children, "greeting" and "title".
children = [
  {
    id = "greeting"
    type = "Label"
  },
  {
    id = "title"
    type = "Label"
  }
]

blocks/newline-in-block.pxf.format:
@type blocks.v1.Doc

# Accept: block entries on their own lines. Binds the same values as
# space-in-block.pxf, through the bare-block form.
address {
  city = "Berlin"
  zip = "10115"
}

blocks/space-in-block.pxf.format:
@type blocks.v1.Doc

# Accept: block entries on one line, separated by spaces. Binds
# address.city to "Berlin" and address.zip to "10115".
address = {
  city = "Berlin"
  zip = "10115"
}

duplicates/err-map-key-twice-across-bind.format:
@type dup.v1.Holder

# Reject: a map key repeated across two bindings of the map field.
labels = {
  a: "1"
}
labels = {
  a: "2"
}

duplicates/err-map-key-twice-in-literal..format:
@type dup.v1.Holder

# Reject: a map key repeated inside one map literal (#396).
labels = {
  a: "1"
  a: "2"
}

duplicates/err-map-key-twice-int-spellin.format:
@type dup.v1.Holder

# Reject: keys compare as values of the key type, so 1 and "1" are one key of an int32-keyed map.
nums = {
  1: "x"
  "1": "y"
}

duplicates/err-map-key-twice-message-val.format:
@type dup.v1.Holder

# Reject: a repeated key in a map of messages; the two values do not merge.
inners = {
  k: {
    a = 1
  }
  k: {
    b = 2
  }
}

duplicates/err-map-key-twice-same-value..format:
@type dup.v1.Holder

# Reject: a repeated map key, even with the same value.
labels = {
  a: "1"
  a: "1"
}

duplicates/err-message-assign-then-block.format:
@type dup.v1.Holder

# Reject: "m = { ... }" and "m { ... }" are the same binding written two ways; both together bind m twice.
m = {
  a = 1
}
m {
  b = 2
}

duplicates/err-message-twice.pxf.format:
@type dup.v1.Holder

# Reject: two blocks for one singular message field bind it twice. They do not merge.
m {
  a = 1
}
m {
  b = 2
}

duplicates/err-nested-scalar-twice.pxf.format:
@type dup.v1.Holder

# Reject: the rule holds in every message body, here a sub-message.
m {
  a = 1
  a = 2
}

duplicates/err-oneof-member-twice.pxf.format:
@type dup.v1.Holder

# Reject: a oneof member bound twice.
km {
  a = 1
}
km {
  a = 1
}

duplicates/map-key-once-per-body.pxf.format:
@type dup.v1.Holder

# Accept: each message body is its own scope, so key a occurs once in each element's map.
items = [
  {
    tags = {
      a: "1"
    }
  },
  {
    tags = {
      a: "2"
    }
  }
]

duplicates/map-twice-distinct-keys.pxf.format:
@type dup.v1.Holder

# Accept: a map field bound twice with distinct keys; the entries merge.
labels = {
  a: "1"
}
labels = {
  b: "2"
}

duplicates/once-per-body.pxf.format:
@type dup.v1.Holder

# Accept: each message body is its own scope. a is bound once in m, once in n and once in each list element.
m {
  a = 1
}
n {
  a = 1
}
items = [
  {
    a = 1
  },
  {
    a = 2
  }
]

duplicates/repeated-twice.pxf.format:
@type dup.v1.Holder

# Accept: a repeated field may be bound more than once; the lists concatenate (#337).
items = [
  {
    a = 1
  }
]
items = [
  {
    a = 2
  }
]

duration/negative-zero.pxf.format:
@type duration.v1.Holder

# "-0s" denotes zero: seconds = 0, nanos = 0.
d = -0s

keyed/anonymous-duplicate-ok.pxf.format:
@type keyed.v1.Node

# Duplicate keys are representable only in the anonymous form. Where the
# schema layer tolerates them (plain decode — no uniqueness constraint
# beyond the keyed block itself), decode accepts, and encode/fmt MUST
# keep the anonymous form: the keyed form requires all keys distinct.
id = "root"
children = [
  {
    id = "dup"
    type = "Label"
  },
  {
    id = "dup"
    type = "HBox"
  }
]

keyed/anonymous-duplicate-ok.pxf.marshal:
id = "root"
children = [
  {
    id = "dup"
    type = "Label"
  },
  {
    id = "dup"
    type = "HBox"
  }
]

keyed/anonymous-equivalence.pxf.format:
@type keyed.v1.Node

# Anonymous-form equivalence: decodes to exactly the same message as
# roundtrip-keyed.pxf (key fields written explicitly, same order).
# fmt canonicalizes this document to the keyed form.
id = "root"
type = "VBox"
children = [
  {
    id = "greeting"
    type = "Label"
    weight = 1
  },
  {
    id = "counter_row"
    type = "HBox"
    weight = 2
  }
]

keyed/anonymous-equivalence.pxf.marshal:
id = "root"
type = "VBox"
children {
  greeting {
    type = "Label"
    weight = 1
  }
  counter_row {
    type = "HBox"
    weight = 2
  }
}

keyed/err-duplicate-key-spelling.pxf.format:
@type keyed.v1.Node

# Spelling-equivalence duplicate: duplicate detection compares UNQUOTED
# values, so "greeting" (quoted) and greeting (bare) are the same key.
# MUST be rejected exactly like err-duplicate-key.pxf.
id = "root"
children {
  greeting {
    type = "Label"
  }
  "greeting" {
    type = "HBox"
  }
}

keyed/err-duplicate-key.pxf.format:
@type keyed.v1.Node

# Duplicate entry names in one keyed block MUST be rejected (decode
# error; diagnostic in tolerant mode).
id = "root"
children {
  greeting {
    type = "Label"
  }
  greeting {
    type = "HBox"
  }
}

keyed/err-empty-key-anonymous.pxf.format:
@type keyed.v1.Node

# The empty-key rule applies in the anonymous form too: an explicit
# empty-string assignment to the key field of an element of a keyed
# repeated field MUST be rejected.
id = "root"
children = [
  {
    id = ""
    type = "Label"
  }
]

keyed/err-empty-key.pxf.format:
@type keyed.v1.Node

# The empty string is not a valid key. A quoted entry name "" MUST be
# rejected.
id = "root"
children {
  "" {
    type = "Label"
  }
}

keyed/err-key-conflict.pxf.format:
@type keyed.v1.Node

# Key conflict: an explicit key-field assignment inside a named entry
# that DISAGREES with the entry name MUST be rejected.
id = "root"
children {
  greeting {
    id = "farewell"
    type = "Label"
  }
}

keyed/err-key-null.pxf.format:
@type keyed.v1.Catalog

# Key conflict: an entry name binds the key field, so binding that field
# to null inside the entry's block disagrees with it and MUST be rejected.
tags {
  alpha {
    name = null
  }
}

keyed/err-key-oneof-sibling-null.pxf.format:
@type keyed.v1.Catalog

# Key conflict: null on another member of the key field's oneof chooses
# that member, so it writes two members and MUST be rejected.
choices {
  alpha {
    other = null
  }
}

keyed/err-key-oneof-sibling.pxf.format:
@type keyed.v1.Catalog

# Key conflict: an entry name binds the key field, so binding another
# member of the key field's oneof writes two members and MUST be rejected.
choices {
  alpha {
    other = "x"
  }
}

keyed/err-quoted-name-unkeyed.pxf.format:
@type keyed.v1.Doc

# 'items' carries no (pxf.key): a quoted entry name is only meaningful
# as a key, so the schema layer MUST reject this document. The parse
# itself succeeds — the grammar accepts quoted entry names everywhere;
# the restriction is schema-layer.
items {
  "a" {
    label = "first"
  }
}

keyed/fmt-anonymous-to-keyed.pxf.format:
@type keyed.v1.Deployment

service = "edge"
regions = [
  {
    name = "us-east-1"
    replicas = 3
  },
  {
    name = "primary"
    replicas = 2
  }
]

keyed/fmt-unquote.pxf.format:
@type keyed.v1.Node

id = "root"
type = "VBox"
children {
  "greeting" {
    id = "greeting"
    type = "Label"
  }
  counter_row {
    type = "HBox"
  }
}

keyed/fmt-unquote.pxf.marshal:
id = "root"
type = "VBox"
children {
  greeting {
    type = "Label"
  }
  counter_row {
    type = "HBox"
  }
}

keyed/key-null-anonymous-ok.pxf.format:
@type keyed.v1.Catalog

# Legal: the anonymous form has no entry name to disagree with, so an
# optional key field may be null. The element's key is absent.
tags = [
  {
    name = null
  }
]

keyed/key-oneof-ok.pxf.format:
@type keyed.v1.Catalog

# Legal: a key in a oneof takes the entry name, an agreeing assignment
# stays redundant, and the anonymous form may choose another member.
choices {
  alpha {
  }
  beta {
    name = "beta"
  }
}
choices = [
  {
    other = "x"
  }
]

keyed/redundant-key-ok.pxf.format:
@type keyed.v1.Node

# An explicit key-field assignment inside a named entry that AGREES with
# the entry name is redundant but legal. Decode accepts; fmt drops the
# redundant assignment when canonicalizing.
id = "root"
children {
  greeting {
    id = "greeting"
    type = "Label"
  }
}

keyed/roundtrip-keyed.pxf.format:
@type keyed.v1.Node

# Keyed round-trip: canonical keyed-block form. Entry name = key-field
# value, entry order = list order; the key field is not repeated inside
# the entry blocks. decode → encode reproduces this body.
id = "root"
type = "VBox"
children {
  greeting {
    type = "Label"
    weight = 1
  }
  counter_row {
    type = "HBox"
    weight = 2
  }
}

keyed/roundtrip-keyed.pxf.marshal:
id = "root"
type = "VBox"
children {
  greeting {
    type = "Label"
    weight = 1
  }
  counter_row {
    type = "HBox"
    weight = 2
  }
}

keyed/roundtrip-quoted.pxf.format:
@type keyed.v1.Deployment

# Quoted-name round-trip: keys that are not identifier-safe are written
# as string-literal entry names and stay quoted in canonical form.
service = "edge"
regions {
  "us-east-1" {
    replicas = 3
  }
  "eu-west-2" {
    replicas = 1
  }
}

map-keys/bool-keys-integer.pxf.format:
@type mapkeys.v1.Flags

# The integer spelling: an integer key matches a bool K "encoded as 0/1".
by_flag = {
  1: "integer one"
  0: "integer zero"
}

map-keys/bool-keys-keyword.pxf.format:
@type mapkeys.v1.Flags

# The keyword spelling: map-key = identifier / string / integer / bool.
by_flag = {
  true: "keyword"
  false: "keyword"
}

map-keys/bool-keys.pxf.format:
@type mapkeys.v1.Flags

# The quoted-literal spelling: a string key is parsed as a literal of
# K's type, and a bool literal is exactly "true" or "false".
by_flag = {
  "true": "quoted literal"
  "false": "quoted literal"
}

map-keys/fmt-dotted-keys.pxf.format:
@type mapkeys.v1.Labels

by_label = {
  a.b: "quoted dotted"
  c.d: "bare dotted"
  ".e": "leading dot"
  "1.5": "float-shaped"
}

map-keys/fmt-dotted-keys.pxf.marshal:
by_label = {
  ".e": "leading dot"
  "1.5": "float-shaped"
  a.b: "quoted dotted"
  c.d: "bare dotted"
}

map-keys/fmt-keyword-keys.pxf.format:
@type mapkeys.v1.Labels

by_label = {
  "true": "quoted keyword"
  "false": "quoted keyword"
  "null": "quoted keyword"
  "123": "quoted integer"
  plain: "quoted identifier-safe key"
  bare: "bare identifier"
}

map-keys/invalid/identifier-lower-f.pxf.format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "f" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  f: "v"
}

map-keys/invalid/identifier-lower-t.pxf.format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "t" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  t: "v"
}

map-keys/invalid/identifier-title-False..format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "False" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  False: "v"
}

map-keys/invalid/identifier-title-True.p.format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "True" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  True: "v"
}

map-keys/invalid/identifier-upper-F.pxf.format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "F" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  F: "v"
}

map-keys/invalid/identifier-upper-FALSE..format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "FALSE" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  FALSE: "v"
}

map-keys/invalid/identifier-upper-T.pxf.format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "T" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  T: "v"
}

map-keys/invalid/identifier-upper-TRUE.p.format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "TRUE" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  TRUE: "v"
}

map-keys/invalid/identifier-word-yes.pxf.format:
@type mapkeys.v1.Flags

# An identifier key on a bool K matches nothing: an identifier names a
# field, and a map has none. "yes" is not a bool literal in any case.
# MUST be rejected.
by_flag = {
  yes: "v"
}

map-keys/invalid/string-lower-t.pxf.format:
@type mapkeys.v1.Flags

# A string key is parsed as a literal of K's type, and a bool literal is
# exactly "true" or "false". "t" is not one. MUST be rejected.
by_flag = {
  t: "v"
}

map-keys/invalid/string-one-1.pxf.format:
@type mapkeys.v1.Flags

# A string key is parsed as a literal of K's type, and a bool literal is
# exactly "true" or "false". "1" is not one. MUST be rejected.
by_flag = {
  "1": "v"
}

map-keys/invalid/string-upper-TRUE.pxf.format:
@type mapkeys.v1.Flags

# A string key is parsed as a literal of K's type, and a bool literal is
# exactly "true" or "false". "TRUE" is not one. MUST be rejected.
by_flag = {
  TRUE: "v"
}

map-keys/invalid/string-zero-0.pxf.format:
@type mapkeys.v1.Flags

# A string key is parsed as a literal of K's type, and a bool literal is
# exactly "true" or "false". "0" is not one. MUST be rejected.
by_flag = {
  "0": "v"
}

nulls/err-list-element.pxf.format:
@type nulls.v1.Holder

# Reject: null as a list element. List elements are not nullable.
l = [
  1,
  null
]

nulls/err-map-message-value.pxf.format:
@type nulls.v1.Holder

# Reject: null as the value of a map entry whose value type is a message.
# The value has presence, but a map entry is not nullable (#380): in
# binary an entry without a value reads back as the empty message.
mm = {
  a: null
}

nulls/err-map-value.pxf.format:
@type nulls.v1.Holder

# Reject: null as the value of a map entry. A map is list-typed for the
# null rule, and its entries are not nullable (#380). Leave the key out
# instead.
m = {
  a: null
}

nulls/err-nested-scalar.pxf.format:
@type nulls.v1.Holder

# Reject: null on a plain proto3 scalar inside a message body. The rule
# applies in every body, not only at the top level.
msg {
  x = null
}

nulls/err-oneof-sibling.pxf.format:
@type nulls.v1.Holder

# Reject: a null oneof member is that member present, so writing it after
# a sibling of the same oneof writes two members.
km {
  x = 1
}
ks = null

nulls/message.pxf.format:
@type nulls.v1.Holder

# Accept: null on a singular message field clears it: msg is unset.
msg = null

postdecode/list-default.pxf.format:
@type postdecode.v1.Root

name = "r"
list = [
  {
    name = "a"
  },
  {
    name = "b"
    tag = "set"
  }
]

postdecode/map-default.pxf.format:
@type postdecode.v1.Root

name = "r"
by_key = {
  k: {
    name = "a"
  }
}
by_num = {
  1: {
    name = "b"
  }
}

postdecode/map-default.pxf.marshal:
name = "r"
by_key = {
  k: {
    name = "a"
  }
}
by_num = {
  1: {
    name = "b"
  }
}

repeated/concat-lists.pxf.format:
@type test.v1.AllTypes

# Entries and Keys: a repeated field MAY be bound more than once with a list
# value. The elements concatenate in document order. MUST be accepted:
# repeated_string = ["a", "b", "c"], repeated_nested names = ["n1", "n2"].
repeated_string = [
  "a"
]
repeated_nested = [
  {
    name = "n1"
  }
]
repeated_string = [
  "b",
  "c"
]
repeated_nested = [
  {
    name = "n2"
    value = 2
  }
]

repeated/err-assigned-block.pxf.format:
@type test.v1.AllTypes

# Entries and Keys: a repeated message field assigned a single block. MUST be
# rejected, like the block-tail form it abbreviates — the element goes in a
# list: repeated_nested = [{ name = "n1" }].
repeated_nested = {
  name = "n1"
}

repeated/err-block-entries.pxf.format:
@type test.v1.AllTypes

# Entries and Keys: a repeated message field written as repeated blocks.
# MUST be rejected — outside the keyed surface form of a keyed repeated
# field, a block on a repeated field is an error. The list form is
# repeated_nested = [{ name = "n1" }, { name = "n2" }].
repeated_nested {
  name = "n1"
}
repeated_nested {
  name = "n2"
}
